"""Plot all common Gkeyll quantities; inventory every frame and report omissions."""
import argparse
import csv
from pathlib import Path
import re
import textwrap
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.backends.backend_pdf import PdfPages
import numpy as np
import postgkyl as pg


def read(path, physical=False):
    d=pg.load(path)
    v=np.asarray(d.values)
    if '_nodes.gkyl' in str(path):
        return d,[np.arange(n) for n in v.shape[:-1]],v
    if physical and str(path).endswith('_mapc2p_vel.gkyl'):
        # velocity_map.c stores independent normalized 1D P1 expansions.
        ndim=v.ndim-1
        if v.shape[-1]!=2*ndim:raise ValueError('Unknown velocity-map layout')
        vr=v
        for k in range(ndim):vr=np.repeat(vr,2,axis=k)
        out=np.empty(vr.shape[:-1]+(ndim,))
        for k in range(ndim):
            shape=[1]*ndim;shape[k]=vr.shape[k]
            xi=np.tile([-.5,.5],v.shape[k]).reshape(shape)
            out[...,k]=vr[...,2*k]/np.sqrt(2)+vr[...,2*k+1]*np.sqrt(1.5)*xi
        edges=[np.linspace(x[0],x[-1],2*v.shape[k]+1) for k,x in enumerate(d.grid)]
        return d,[.5*(x[:-1]+x[1:]) for x in edges],out
    meta=d.ctx.get('_load_metadata',{}).get('file_metadata',{})
    if physical and 'basis_type' in meta and 'poly_order' in meta and not str(path).endswith('_jacobvel.gkyl'):
        if d.ctx.get('value_form')=='quad':d=d.represent(to='modal')
        if d.ctx.get('value_form') in ['modal','nodal']:d=d.interpolate(num_interp=2)
        v=np.asarray(d.values)
    x=[.5*(a[:-1]+a[1:]) if len(a)==v.shape[k]+1 else a for k,a in enumerate(d.grid)]
    if any(len(a)!=v.shape[k] for k,a in enumerate(x)):raise ValueError('Grid/value shape mismatch')
    return d,x,v


def compatible(a,b):
    da,xa,va=a;db,xb,vb=b
    return va.shape==vb.shape and len(xa)==len(xb) and all(np.array_equal(x,y) for x,y in zip(xa,xb)) and np.isclose(da.ctx.get('time',0),db.ctx.get('time',0),rtol=1e-10,atol=1e-14)


def textpage(pdf,title,lines):
    lines=[part for line in lines for part in (textwrap.wrap(str(line),125) or [''])]
    for start in range(0,max(1,len(lines)),42):
        fig=plt.figure(figsize=(11.7,8.3))
        fig.text(.05,.94,title,fontsize=14)
        fig.text(.05,.89,'\n'.join(lines[start:start+42]),fontsize=9,va='top',family='monospace')
        pdf.savefig(fig);plt.close(fig)


def stats(u,v):
    mask=np.isfinite(u)&np.isfinite(v)
    if not mask.any():return float('nan'),float('nan')
    err=float(np.max(np.abs(v[mask]-u[mask])))
    scale=max(float(np.max(np.abs(u[mask]))),float(np.max(np.abs(v[mask]))),1e-300)
    return err,err/scale


def plot_pair(pdf,title,pa,pb):
    a,b=read(pa,True),read(pb,True)
    da,xa,va=a;db,xb,vb=b
    if va.ndim!=vb.ndim or va.shape[-1]!=vb.shape[-1]:raise ValueError(f'Component/dimension mismatch: {va.shape}, {vb.shape}')
    same=compatible(a,b);ndim=va.ndim-1
    if '_nodes.gkyl' in str(pa):title+='\nAxes are node indices, not uniform physical coordinates'
    meta=da.ctx.get('_load_metadata',{}).get('file_metadata',{})
    if ndim>1 and not ('basis_type' in meta and 'poly_order' in meta) and not str(pa).endswith(('_jacobvel.gkyl','_mapc2p_vel.gkyl')):
        title+='\nStored components; no DG basis metadata available'
    for first in range(0,va.shape[-1],3):
        count=min(3,va.shape[-1]-first)
        fig,axes=plt.subplots(count,3,figsize=(14,3*count+1.3),squeeze=False)
        for row,comp in enumerate(range(first,first+count)):
            u,v=va[...,comp],vb[...,comp];ax=axes[row]
            if ndim==1:
                ax[0].plot(xa[0],u,label='main',lw=1.5)
                ax[0].plot(xb[0],v,'--',label='branch',lw=1)
                ax[0].legend(fontsize=7);ax[0].set_title(f'Component {comp}: overlay')
                ax[0].set_xlabel('Time' if 'basis_type' not in meta else 'Coordinate 0')
                if same:
                    delta=v-u
                    scale=max(float(np.max(np.abs(u))),float(np.max(np.abs(v))),1e-300)
                    ax[1].plot(xa[0],delta);ax[1].set_title('Branch - main')
                    ax[2].plot(xa[0],delta/scale);ax[2].set_title('Difference / global max magnitude')
                else:
                    ax[1].text(.1,.5,'Unequal coordinates or times;\nno pointwise subtraction.',transform=ax[1].transAxes);ax[2].axis('off')
            else:
                delta=v-u if same else None
                idx=np.unravel_index(np.argmax(np.where(np.isfinite(delta),np.abs(delta),-1)),u.shape)[:-2] if same else tuple(n//2 for n in u.shape[:-2])
                idxb=idx if same else tuple(n//2 for n in v.shape[:-2])
                us,vs=u[idx],v[idxb]
                finite=np.concatenate([us[np.isfinite(us)],vs[np.isfinite(vs)]])
                lo,hi=(float(finite.min()),float(finite.max())) if finite.size else (0.,1.)
                if lo==hi:hi=lo+max(abs(lo)*1e-12,1e-300)
                for axis,x,value,label in [(ax[0],xa,us,'main'),(ax[1],xb,vs,'branch')]:
                    im=axis.pcolormesh(x[-2],x[-1],value.T,shading='nearest',vmin=lo,vmax=hi,rasterized=True)
                    fig.colorbar(im,ax=axis,shrink=.8);axis.set_title(f'Component {comp}: {label}')
                    axis.set_xlabel(f'Coordinate {ndim-2}');axis.set_ylabel(f'Coordinate {ndim-1}')
                if same:
                    ds=vs-us;finite=ds[np.isfinite(ds)]
                    lim=max(float(np.max(np.abs(finite))),1e-300) if finite.size else 1.
                    im=ax[2].pcolormesh(xa[-2],xa[-1],ds.T,shading='nearest',cmap='RdBu_r',vmin=-lim,vmax=lim,rasterized=True)
                    fig.colorbar(im,ax=ax[2],shrink=.8);ax[2].set_title('Branch - main')
                else:ax[2].text(.1,.5,'Unequal grids/times;\nno pointwise subtraction.',transform=ax[2].transAxes)
                cut=', '.join(f'x{k}={xa[k][i]:.5g}' for k,i in enumerate(idx)) or 'full 2D domain'
                ax[0].text(0,-.28,'Slice: '+cut,transform=ax[0].transAxes,fontsize=7)
            if same:
                error,relative=stats(u,v)
                ax[2].set_xlabel(f'Full domain: max |delta|={error:.3g}; normalized={relative:.3g}\nNonfinite main/branch: {np.sum(~np.isfinite(u))}/{np.sum(~np.isfinite(v))}',fontsize=7)
            for axis in ax:axis.tick_params(labelsize=7)
        fig.suptitle(title+f'\nt(main)={da.ctx.get("time","history")}; t(branch)={db.ctx.get("time","history")}',fontsize=10)
        fig.tight_layout(rect=(0,0,.99,.92));pdf.savefig(fig,dpi=110);plt.close(fig)


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    for arg in ['baseline','candidate','output']:ap.add_argument('--'+arg,type=Path,required=True)
    ap.add_argument('--test',required=True);ap.add_argument('--mode',default='cpu_serial')
    args=ap.parse_args();args.output.mkdir(parents=True,exist_ok=True)
    aa=list(args.baseline.glob(f'*/creg-accepted/{args.mode}/{args.test}'))
    bb=list(args.candidate.glob(f'*/creg-runs/{args.mode}/{args.test}'))
    rows=[];issues=[]
    with PdfPages(args.output/'comparisons.pdf') as pdf:
        if len(aa)!=1 or len(bb)!=1:
            issues.append(f'{args.test}: missing/ambiguous output directories: {len(aa)}, {len(bb)}')
            textpage(pdf,args.test,issues)
        else:
            af={p.name:p for p in aa[0].glob('*.gkyl')};bf={p.name:p for p in bb[0].glob('*.gkyl')};groups={}
            for name in sorted(af.keys()|bf.keys()):
                match=re.match(r'(.*)_(\d+)\.gkyl$',name)
                quantity,frame=(match[1],int(match[2])) if match else (name[:-5],-1)
                row=dict(mode=args.mode,test=args.test,file=name,status='ok',max_abs='',normalized='',frame=frame,time_main='',time_branch='')
                try:
                    if name not in af or name not in bf:raise ValueError('missing in '+('main' if name not in af else 'branch'))
                    a,b=read(af[name]),read(bf[name])
                    row['time_main']=a[0].ctx.get('time','');row['time_branch']=b[0].ctx.get('time','')
                    if compatible(a,b):
                        row['max_abs'],row['normalized']=stats(a[2],b[2])
                        if not np.all(np.isfinite(a[2])) or not np.all(np.isfinite(b[2])):row['status']='nonfinite values'
                    else:row['status']='grid, shape, or time mismatch'
                    groups.setdefault(quantity,[]).append(row)
                except Exception as exc:row['status']=str(exc)
                rows.append(row)
                if row['status']!='ok':issues.append(name+': '+row['status'])
            textpage(pdf,args.mode+': '+args.test,[f'{len(af)} baseline files; {len(bf)} branch files; {len(groups)} common quantities.']+issues)
            for quantity,frames in sorted(groups.items()):
                final=max(frames,key=lambda x:x['frame'])
                comparable=[r for r in frames if isinstance(r['normalized'],float) and np.isfinite(r['normalized'])]
                worst=max(comparable,key=lambda x:x['normalized']) if comparable else final
                for row in [final]+([worst] if worst['file']!=final['file'] else []):
                    try:plot_pair(pdf,args.test+'\n'+row['file'],af[row['file']],bf[row['file']])
                    except Exception as exc:
                        issues.append(row['file']+': plot failed: '+str(exc));textpage(pdf,row['file'],[str(exc)])
    with (args.output/'inventory.csv').open('w') as out:
        w=csv.DictWriter(out,fieldnames=['mode','test','file','status','max_abs','normalized','frame','time_main','time_branch']);w.writeheader();w.writerows(rows)
    (args.output/'exceptions.txt').write_text('\n'.join(issues)+'\n')
    print(args.test,len(rows),'files;',len(issues),'exceptions',flush=True)


if __name__=='__main__':main()
